/* saleson.shop.order.shipping.OrderShippingMapper.getOrderShippingByParam */

SELECT * FROM OP_ORDER_SHIPPING
WHERE
	ORDER_CODE = #{orderCode}
	AND ORDER_SEQUENCE = #{orderSequence}
	AND SHIPPING_SEQUENCE = #{shippingSequence}

/* saleson.shop.order.shipping.OrderShippingMapper.getOrderItemListByShippingParam */
SELECT * FROM OP_ORDER_ITEM
WHERE
	ORDER_CODE = #{orderCode}
	AND ORDER_SEQUENCE = #{orderSequence}
	AND SHIPPING_SEQUENCE = #{shippingSequence}
	AND CANCEL_FLAG = 'N'
	AND REFUND_STATUS != '1'

/* saleson.shop.order.shipping.OrderShippingMapper.getBuyShippingCompleteListByParam */ SELECT OI.* FROM OP_ORDER_ITEM OI INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' WHERE OI.CANCEL_FLAG = 'N'
AND OI.ORDER_STATUS IN ('30') AND OI.DELIVERY_COMPANY_ID NOT IN ('29','31') AND OI.DELIVERY_NUMBER IS NOT NULL
AND OI.ORDER_STATUS IN ('30', '55')
AND LEFT(OI.SHIPPING_DATE, 8) <= DATE_FORMAT(ADDDATE(NOW(), interval -#{shippingCompleteDate} DAY) ,'%Y%m%d')
ORDER BY OI.ORDER_CODE LIMIT 100 OFFSET #{page}

