mapper.insert:
/* saleson.shop.order.shipping.OrderShippingMapper.copyOrderItemForShippingReady */
SELECT IFNULL(MAX(ITEM_SEQUENCE), 0) + 1 FROM OP_ORDER_ITEM WHERE ORDER_CODE = #{orderCode} AND ORDER_SEQUENCE = #{orderSequence}
INSERT INTO OP_ORDER_ITEM ( , ORDER_STATUS, ITEM_SEQUENCE, QUANTITY, CLAIM_QUANTITY, ORDER_QUANTITY, PAY_DATE, SALES_DATE, SALES_CANCEL_DATE, SHIPPING_READY_DATE, SHIPPING_DATE, SHIPPING_FINISH_DATE, CANCEL_REQUEST_DATE, CANCEL_REQUEST_FINISH_DATE, CONFIRM_DATE, RETURN_REQUEST_DATE, RETURN_REQUEST_FINISH_DATE, EXCHANGE_REQUEST_DATE, CANCEL_FLAG, CREATED_DATE, REFUND_STATUS, LOCGOV_CODE ) SELECT , '20', #{copyItemSequence}, #{quantity}, 0, #{quantity},
PAY_DATE, SALES_DATE, SALES_CANCEL_DATE, , SHIPPING_DATE, SHIPPING_FINISH_DATE, CANCEL_REQUEST_DATE, CANCEL_REQUEST_FINISH_DATE, CONFIRM_DATE, RETURN_REQUEST_DATE, RETURN_REQUEST_FINISH_DATE, EXCHANGE_REQUEST_DATE, CANCEL_FLAG, , REFUND_STATUS, LOCGOV_CODE
FROM OP_ORDER_ITEM WHERE ORDER_CODE = #{orderCode} AND ORDER_SEQUENCE = #{orderSequence} AND ITEM_SEQUENCE = #{itemSequence}

/* saleson.shop.order.shipping.OrderShippingMapper.copyOrderItemForShippingDirect */
SELECT IFNULL(MAX(ITEM_SEQUENCE), 0) + 1 FROM OP_ORDER_ITEM WHERE ORDER_CODE = #{orderCode} AND ORDER_SEQUENCE = #{orderSequence}
INSERT INTO OP_ORDER_ITEM ( , ORDER_STATUS, ITEM_SEQUENCE, QUANTITY, CLAIM_QUANTITY, ORDER_QUANTITY, PAY_DATE, SALES_DATE, SALES_CANCEL_DATE, SHIPPING_READY_DATE, SHIPPING_DATE, SHIPPING_FINISH_DATE, CANCEL_REQUEST_DATE, CANCEL_REQUEST_FINISH_DATE, CONFIRM_DATE, RETURN_REQUEST_DATE, RETURN_REQUEST_FINISH_DATE, EXCHANGE_REQUEST_DATE, CANCEL_FLAG, CREATED_DATE, REFUND_STATUS, LOCGOV_CODE ) SELECT , '35', #{copyItemSequence}, #{quantity}, 0, #{quantity},
PAY_DATE, SALES_DATE, SALES_CANCEL_DATE, , , , CANCEL_REQUEST_DATE, CANCEL_REQUEST_FINISH_DATE, CONFIRM_DATE, RETURN_REQUEST_DATE, RETURN_REQUEST_FINISH_DATE, EXCHANGE_REQUEST_DATE, CANCEL_FLAG, , REFUND_STATUS, LOCGOV_CODE FROM OP_ORDER_ITEM WHERE ORDER_CODE = #{orderCode} AND ORDER_SEQUENCE = #{orderSequence} AND ITEM_SEQUENCE = #{itemSequence}

mapper.update:
/* saleson.shop.order.shipping.OrderShippingMapper.updateShippingReady */
UPDATE OP_ORDER_ITEM OI
SET
	OI.SHIPPING_READY_DATE = ,
	OI.SALES_DATE = (CASE WHEN OI.REVENUE_SALES_STATUS = '20' THEN  ELSE OI.SALES_DATE END),

	OI.UPDATED_ADMIN_USER_NAME = #{adminUserName},
	OI.ORDER_STATUS = '20'



		OI.SELLER_ID = #{sellerId}
		AND OI.DELIVERY_TYPE = '2'

	AND OI.ORDER_CODE = #{orderCode}
	AND OI.ORDER_SEQUENCE = #{orderSequence}
	AND OI.ITEM_SEQUENCE = #{itemSequence}

/* saleson.shop.order.shipping.OrderShippingMapper.updateShippingDirect */
UPDATE OP_ORDER_ITEM OI
SET
	OI.SHIPPING_READY_DATE = ,
	OI.SHIPPING_DATE = ,
	OI.SALES_DATE = (CASE WHEN OI.REVENUE_SALES_STATUS = '20' THEN  ELSE OI.SALES_DATE END),

	OI.UPDATED_ADMIN_USER_NAME = #{adminUserName},
	OI.ORDER_STATUS = '35'



		OI.SELLER_ID = #{sellerId}
		AND OI.DELIVERY_TYPE = '2'

	AND OI.ORDER_CODE = #{orderCode}
	AND OI.ORDER_SEQUENCE = #{orderSequence}
	AND OI.ITEM_SEQUENCE = #{itemSequence}

/* saleson.shop.order.shipping.OrderShippingMapper.updateShippingReadyCancel */
UPDATE OP_ORDER_ITEM OI
SET
	OI.SHIPPING_READY_DATE = '00000000000000',
	OI.SALES_DATE = (CASE WHEN OI.REVENUE_SALES_STATUS = '20' THEN '' ELSE OI.SALES_DATE END),

	OI.UPDATED_ADMIN_USER_NAME = #{adminUserName},
	OI.ORDER_STATUS = '10'



		OI.SELLER_ID = #{sellerId}
		AND OI.DELIVERY_TYPE = '2'

	AND OI.ORDER_CODE = #{orderCode}
	AND OI.ORDER_SEQUENCE = #{orderSequence}
	AND OI.ITEM_SEQUENCE = #{itemSequence}

