	OI.UPDATED_ADMIN_USER_NAME = #{adminUserName},
	OI.ORDER_STATUS = '35'
WHERE OI.ORDER_CODE = #{orderCode}
  AND OI.ORDER_SEQUENCE = #{orderSequence}
  AND OI.ITEM_SEQUENCE = #{itemSequence}

/* saleson.shop.order.shipping.OrderShippingMapper.updateShippingCancel */
UPDATE OP_ORDER_ITEM
SET SHIPPING_DATE = '00000000000000',
	DELIVERY_COMPANY_ID = #{deliveryCompanyId},
	DELIVERY_COMPANY_NAME = #{deliveryCompanyName},
	DELIVERY_NUMBER = null,
	DELIVERY_COMPANY_URL = null,
	ORDER_STATUS = '20'
WHERE
	ORDER_CODE = #{orderCode}
	AND ORDER_SEQUENCE = #{orderSequence}
	AND ITEM_SEQUENCE = #{itemSequence}

/* saleson.shop.order.shipping.OrderShippingMapper.updateShippingNumber */
UPDATE OP_ORDER_ITEM SET
	DELIVERY_COMPANY_ID = #{deliveryCompanyId},
	DELIVERY_COMPANY_NAME = #{deliveryCompanyName},
	DELIVERY_NUMBER = #{deliveryNumber},
	DELIVERY_COMPANY_URL = #{deliveryCompanyUrl}
WHERE
	ORDER_CODE = #{orderCode}
	AND ORDER_SEQUENCE = #{orderSequence}
	AND ITEM_SEQUENCE = #{itemSequence}

/* saleson.shop.order.shipping.OrderShippingMapper.updateConfirmPurchase */ UPDATE OP_ORDER_ITEM OI INNER JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID SET OI.SHIPPING_FINISH_DATE = ( CASE WHEN OI.SHIPPING_FINISH_DATE = '00000000000000' THEN
ELSE OI.SHIPPING_FINISH_DATE END ), OI.CONFIRM_DATE = ,
OI.REMITTANCE_TYPE = (CASE WHEN OI.REMITTANCE_ID IS NULL OR OI.REMITTANCE_ID = 0 THEN S.REMITTANCE_TYPE ELSE OI.REMITTANCE_TYPE END), OI.REMITTANCE_DAY = (CASE WHEN OI.REMITTANCE_ID IS NULL OR OI.REMITTANCE_ID = 0 THEN S.REMITTANCE_DAY ELSE OI.REMITTANCE_DAY END), OI.REMITTANCE_EXPECTED_DATE = (CASE WHEN OI.REMITTANCE_ID IS NULL OR OI.REMITTANCE_ID = 0 THEN #{remittanceDate} ELSE OI.REMITTANCE_EXPECTED_DATE END),
OI.ORDER_STATUS = '40' WHERE OI.ORDER_CODE = #{orderCode} AND OI.ORDER_SEQUENCE = #{orderSequence} AND OI.ITEM_SEQUENCE = #{itemSequence}
AND OI.USER_ID = #{userId} AND OI.GUEST_FLAG = 'N'
AND OI.GUEST_FLAG = 'Y'

/* saleson.shop.order.shipping.OrderShippingMapper.updateShppingComplete */
UPDATE OP_ORDER_ITEM OI
SET
	OI.SHIPPING_FINISH_DATE = ,
	OI.ORDER_STATUS = DECODE(OI.ORDER_STATUS, '30', '35', '55', '58')
WHERE
	OI.ORDER_CODE = #{orderCode}
	AND OI.ORDER_SEQUENCE = #{orderSequence}
	AND OI.ITEM_SEQUENCE = #{itemSequence}

	/* saleson.shop.order.shipping.OrderShippingMapper.updateOpOrderExchangeApplyClaimStatus */
    UPDATE OP_ORDER_EXCHANGE_APPLY OI
    SET
        OI.UPDATED_DATE = ,
        OI.CLAIM_STATUS = '04'
    WHERE
        OI.ORDER_CODE = #{orderCode}
        AND OI.ORDER_SEQUENCE = #{orderSequence}
        AND OI.ITEM_SEQUENCE = #{itemSequence}

/* saleson.shop.order.shipping.OrderShippingMapper.updateShippingRemittanceDate */
UPDATE OP_ORDER_SHIPPING SET
	REMITTANCE_EXPECTED_DATE = #{remittanceDate}
WHERE
	ORDER_CODE = #{orderCode}
	AND ORDER_SEQUENCE = #{orderSequence}
	AND SHIPPING_SEQUENCE = #{shippingSequence}
	AND REMITTANCE_AMOUNT > 0


	AND (REMITTANCE_ID IS NULL OR REMITTANCE_ID = 0)

	AND IFNULL(REMITTANCE_EXPECTED_DATE, '') = ''

	/* saleson.shop.order.shipping.OrderShippingMapper.updateCancelShipping */
    UPDATE OP_ORDER_SHIPPING
    SET
    PAY_SHIPPING = #{payShipping},
    REAL_SHIPPING = #{realShipping},
    SHIPPING_PAYMENT_TYPE = #{shippingPaymentType},
    REMITTANCE_AMOUNT = #{remittanceAmount},
    RETURN_SHIPPING = #{returnShipping}




        , REMITTANCE_EXPECTED_DATE = #{remittanceExpectedDate}

        , REMITTANCE_DATE = ''
        , RETURN_FLAG = #{returnFlag}


    WHERE
    ORDER_CODE = #{orderCode}
    AND ORDER_SEQUENCE = #{orderSequence}
    AND SHIPPING_SEQUENCE = #{shippingSequence}




        AND REMITTANCE_ID IS NOT NULL

	/* saleson.shop.order.shipping.OrderShippingMapper.updatePreviousShipping */
    UPDATE OP_ORDER_SHIPPING
    SET
        PREVIOUS_REAL_SHIPPING = REAL_SHIPPING,
        PREVIOUS_PAY_SHIPPING = PAY_SHIPPING,
        PREVIOUS_REMITTANCE_AMOUNT = REMITTANCE_AMOUNT,
        PREVIOUS_RETURN_SHIPPING = RETURN_SHIPPING
    WHERE
        ORDER_CODE = #{orderCode}
        AND ORDER_SEQUENCE = #{orderSequence}

	/* saleson.shop.order.shipping.OrderShippingMapper.updateShippingForCancelRefund */
    UPDATE OP_ORDER_SHIPPING
    SET
        REAL_SHIPPING = PREVIOUS_REAL_SHIPPING,
        PAY_SHIPPING = PREVIOUS_PAY_SHIPPING,
        REMITTANCE_AMOUNT = PREVIOUS_REMITTANCE_AMOUNT,
        RETURN_SHIPPING = PREVIOUS_RETURN_SHIPPING
    WHERE
        ORDER_CODE = #{orderCode}
        AND ORDER_SEQUENCE = #{orderSequence}
        AND SHIPPING_SEQUENCE = #{shippingSequence}

mapper.select:
	/* saleson.shop.order.shipping.OrderShippingMapper.getPreShippingCount */
    SELECT COUNT(*)
    FROM OP_ORDER_ITEM
    WHERE ORDER_CODE = #{orderCode}
    AND ORDER_STATUS < 30
    AND ITEM_SEQUENCE != #{itemSequence};

mapper.update:
/* saleson.shop.order.shipping.OrderShippingMapper.updateTempShippingMobile */
UPDATE OP_ORDER_ITEM OI
SET
	OI.MOBILE_NUMBER = #{mobileNumber},

	OI.UPDATED_ADMIN_USER_NAME = #{adminUserName}
WHERE OI.ORDER_CODE = #{orderCode}
  AND OI.ORDER_SEQUENCE = #{orderSequence}
  AND OI.ITEM_SEQUENCE = #{itemSequence}
